@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology/edifact-invoice-story>
    a owl:Ontology ;
    rdfs:label "EDIFACT Invoice Ontology" ;
    rdfs:comment "Ontology for representing UN/EDIFACT invoice messages, organizations, roles, and line items as described in the story." .

#################################################################
# Classes
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The top-level envelope in an EDIFACT message, containing messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A business message contained in an Interchange Envelope." .

:InvoiceMessage a owl:Class ;
    rdfs:subClassOf :Message ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "A type of message representing an invoice, composed of header, detail, and summary sections." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment within a message, such as BGM or NAD." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element within a segment." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element within a composite data element or segment." .

:HeaderSection a owl:Class ;
    rdfs:label "Header Section" ;
    rdfs:comment "The header section of an invoice message containing document dates and reference numbers." .

:DetailSection a owl:Class ;
    rdfs:label "Detail Section" ;
    rdfs:comment "The detail section listing line items in the invoice." .

:SummarySection a owl:Class ;
    rdfs:label "Summary Section" ;
    rdfs:comment "The summary section providing total tax and invoice amounts." .

:LineItem a owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "A line item in the detail section, referencing an item, quantity, and net price." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "An item sold in the invoice." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "An organization involved in the invoice, such as buyer or delivery party." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in the context of the invoice (e.g., Buyer, Delivery Party)." .

:OrganizationRoleAssignment a owl:Class ;
    rdfs:label "Organization Role Assignment" ;
    rdfs:comment "A pivot class reifying the assignment of a role and address to an organization in an invoice." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A postal address (e.g., headquarters or warehouse) associated with an organization role assignment." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "A formal identifier such as a Global Location Number used in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A price value associated with a line item." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice can be assigned." .

#################################################################
# Object Properties
#################################################################

:containsMessage a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    rdfs:label "contains message" ;
    rdfs:comment "Links an Interchange Envelope to the contained Message(s)." .

:hasSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    rdfs:label "has segment" ;
    rdfs:comment "Links a message to its segments." .

:hasSection a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range rdf:Resource ;
    rdfs:label "has section" ;
    rdfs:comment "Links an invoice message to one of its sections (header, detail, summary)." .

:hasHeader a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :HeaderSection ;
    rdfs:label "has header" ;
    rdfs:comment "Links an invoice message to its header section." .

:hasDetail a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :DetailSection ;
    rdfs:label "has detail" ;
    rdfs:comment "Links an invoice message to its detail section." .

:hasSummary a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :SummarySection ;
    rdfs:label "has summary" ;
    rdfs:comment "Links an invoice message to its summary section." .

:hasLineItem a owl:ObjectProperty ;
    rdfs:domain :DetailSection ;
    rdfs:range :LineItem ;
    rdfs:label "has line item" ;
    rdfs:comment "Links a detail section to its line items." .

:hasItem a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Item ;
    rdfs:label "has item" ;
    rdfs:comment "Links a line item to the item being sold." .

:hasNetPrice a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Price ;
    rdfs:label "has net price" ;
    rdfs:comment "Links a line item to its net price." .

:hasOrganizationRoleAssignment a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "has organization role assignment" ;
    rdfs:comment "Links an invoice message to an organization role assignment (pivot class)." .

:involvesOrganization a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :Organization ;
    rdfs:label "involves organization" ;
    rdfs:comment "Links an organization role assignment to the involved organization." .

:hasAgentRole a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :AgentRole ;
    rdfs:label "has agent role" ;
    rdfs:comment "Links an organization role assignment to the agent role played." .

:hasAddress a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :Address ;
    rdfs:label "has address" ;
    rdfs:comment "Links an organization role assignment to an address (e.g., headquarters or warehouse)." .

:hasIdentifier a owl:ObjectProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :Identifier ;
    rdfs:label "has identifier" ;
    rdfs:comment "Links an organization role assignment to an identifier (e.g., GLN)." .

:hasBusinessProcess a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess ;
    rdfs:label "has business process" ;
    rdfs:comment "Links an invoice message to a business process." .

#################################################################
# Data Properties
#################################################################

:roleType a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :AgentRole ;
    rdfs:range xsd:string ;
    rdfs:label "role type" ;
    rdfs:comment "The type of role played by an agent (e.g., Buyer, Delivery Party)." .

:addressLine a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "address line" ;
    rdfs:comment "The address line of an address." .

:city a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "city" ;
    rdfs:comment "The city of an address." .

:postalCode a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "postal code" ;
    rdfs:comment "The postal code of an address." .

:countryCode a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "country code" ;
    rdfs:comment "The country code of an address." .

:identifierValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Identifier ;
    rdfs:range xsd:string ;
    rdfs:label "identifier value" ;
    rdfs:comment "The value of an identifier (e.g., GLN number)." .

:identifierScheme a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Identifier ;
    rdfs:range xsd:string ;
    rdfs:label "identifier scheme" ;
    rdfs:comment "The scheme or type of identifier (e.g., GLN, VAT)." .

:hasQuantity a owl:DatatypeProperty ;
    rdfs:domain :LineItem ;
    rdfs:range xsd:decimal ;
    rdfs:label "has quantity" ;
    rdfs:comment "The quantity of the item in the line item." .

:itemDescription a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Item ;
    rdfs:range xsd:string ;
    rdfs:label "item description" ;
    rdfs:comment "A description of the item sold." .

:priceAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Price ;
    rdfs:range xsd:decimal ;
    rdfs:label "price amount" ;
    rdfs:comment "The net price amount for a line item." .

:invoiceAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range xsd:decimal ;
    rdfs:label "invoice amount" ;
    rdfs:comment "The invoice total amount." .

:totalTaxAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range xsd:decimal ;
    rdfs:label "total tax amount" ;
    rdfs:comment "Total tax amount in the summary section." .

:invoiceNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string ;
    rdfs:label "invoice number" ;
    rdfs:comment "The invoice number in the header section." .

:invoiceDate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:dateTime ;
    rdfs:label "invoice date" ;
    rdfs:comment "The invoice date in the header section." .

#################################################################
# Restrictions and Axioms
#################################################################

# InvoiceMessage must have exactly one header, detail, and summary section
:InvoiceMessage rdfs:subClassOf [
    a owl:Restriction ;
    owl:onProperty :hasHeader ;
    owl:cardinality "1"^^xsd:nonNegativeInteger
] , [
    a owl:Restriction ;
    owl:onProperty :hasDetail ;
    owl:cardinality "1"^^xsd:nonNegativeInteger
] , [
    a owl:Restriction ;
    owl:onProperty :hasSummary ;
    owl:cardinality "1"^^xsd:nonNegativeInteger
] .

# DetailSection must have at least one line item
:DetailSection rdfs:subClassOf [
    a owl:Restriction ;
    owl:onProperty :hasLineItem ;
    owl:minCardinality "1"^^xsd:nonNegativeInteger
] .

# OrganizationRoleAssignment must have exactly one organization, one agent role, and one address
:OrganizationRoleAssignment rdfs:subClassOf [
    a owl:Restriction ;
    owl:onProperty :involvesOrganization ;
    owl:cardinality "1"^^xsd:nonNegativeInteger
] , [
    a owl:Restriction ;
    owl:onProperty :hasAgentRole ;
    owl:cardinality "1"^^xsd:nonNegativeInteger
] , [
    a owl:Restriction ;
    owl:onProperty :hasAddress ;
    owl:cardinality "1"^^xsd:nonNegativeInteger
] .

# Disjointness axioms
:Organization owl:disjointWith :Item , :Address , :AgentRole .
:Message owl:disjointWith :Segment .
:Segment owl:disjointWith :CompositeDataElement .
:CompositeDataElement owl:disjointWith :SimpleDataElement .
:HeaderSection owl:disjointWith :DetailSection , :SummarySection .
:DetailSection owl:disjointWith :SummarySection .

