# InvoiceMessage must have exactly one header, detail, and summary section
:InvoiceMessage rdfs:subClassOf [
    a owl:Restriction ;
    owl:onProperty :hasHeader ;
    owl:cardinality "1"^^xsd:nonNegativeInteger
] , [
    a owl:Restriction ;
    owl:onProperty :hasDetail ;
    owl:cardinality "1"^^xsd:nonNegativeInteger
] , [
    a owl:Restriction ;
    owl:onProperty :hasSummary ;
    owl:cardinality "1"^^xsd:nonNegativeInteger
] .

# DetailSection must have at least one line item
:DetailSection rdfs:subClassOf [
    a owl:Restriction ;
    owl:onProperty :hasLineItem ;
    owl:minCardinality "1"^^xsd:nonNegativeInteger
] .

# OrganizationRoleAssignment must have exactly one organization, one agent role, and one address
:OrganizationRoleAssignment rdfs:subClassOf [
    a owl:Restriction ;
    owl:onProperty :involvesOrganization ;
    owl:cardinality "1"^^xsd:nonNegativeInteger
] , [
    a owl:Restriction ;
    owl:onProperty :hasAgentRole ;
    owl:cardinality "1"^^xsd:nonNegativeInteger
] , [
    a owl:Restriction ;
    owl:onProperty :hasAddress ;
    owl:cardinality "1"^^xsd:nonNegativeInteger
] .

# Disjointness axioms
:Organization owl:disjointWith :Item , :Address , :AgentRole .
:Message owl:disjointWith :Segment .
:Segment owl:disjointWith :CompositeDataElement .
:CompositeDataElement owl:disjointWith :SimpleDataElement .
:HeaderSection owl:disjointWith :DetailSection , :SummarySection .
:DetailSection owl:disjointWith :SummarySection .

